import { headers } from 'next/headers'

export default async function NotFound() {
 const headersList = await headers()
 const domain = headersList.get('host')
 const data = await getSiteData(domain)
 return (

 Not Found: {data.name} 
 Could not find requested resource 

 View all posts 


 )
}

```

If you need to use Client Component hooks like `usePathname` to display content based on the path, you must fetch data on the client-side instead.

### Metadata

For `global-not-found.js`, you can export a `metadata` object or a [`generateMetadata`](https://nextjs.org/docs/app/api-reference/functions/generate-metadata) function to customize the ``, ` `, and other head tags for your 404 page:

> Good to know: Next.js automatically injects ` ` for pages that return a 404 status code, including `global-not-found.js` pages.

```tsx
import type { Metadata } from 'next'

export const metadata: Metadata = {
 title: 'Not Found',
 description: 'The page you are looking for does not exist.',
}

export default function GlobalNotFound() {
 return (



 Not Found 
 The page you are looking for does not exist. 



 )
}

```

```jsx
export const metadata = {
 title: 'Not Found',
 description: 'The page you are looking for does not exist.',
}

export default function GlobalNotFound() {
 return (



 Not Found 
 The page you are looking for does not exist. 



 )
}

```

## Version History

| Version | Changes |
| --- | --- |
| `v15.4.0` | `global-not-found.js` introduced (experimental). |
| `v13.3.0` | Root `app/not-found` handles global unmatched URLs. |
| `v13.0.0` | `not-found` introduced. |

---

For an overview of all available documentation, see [/docs/llms.txt](https://nextjs.org/docs/llms.txt)

