args.streamContent:
import { notFound } from 'next/navigation';
import BlogPostClient from './BlogPostClient';

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  body: string;
  email: string;
}

async function getPostData(id: string): Promise<{
  post: Post;
  comments: Comment[];
} | null> {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`, {
        next: { revalidate: 300 },
      }),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`, {
        next: { revalidate: 300 },
      }),
    ]);

    if (!postRes.ok) return null;

    const [post, comments] = await Promise.all([
      postRes.json(),
      commentsRes.json(),
    ]);

    return { post, comments };
  } catch {
    return null;
  }
}

export async function generateStaticParams() {
  const posts = await fetch('https://jsonplaceholder.typicode.com/posts').then(
    (res) => res.json()
  );

  return posts.slice(0, 10).map((post: Post) => ({
    id: post.id.toString(),
  }));
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const data = await getPostData(id);
  if (!data) return { title: 'Post Not Found - My Blog' };

  const description = data.post.body.substring(0, 160);
  return {
    title: `${data.post.title} - My Blog`,
    description,
    openGraph: {
      title: data.post.title,
      description,
    },
  };
}

export default async function BlogPostPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = await params;
  const data = await getPostData(id);

  if (!data) {
    notFound();
  }

  return (
    <BlogPostClient post={data.post} comments={data.comments} />
  );
}

