'use client';

import { useRouter } from 'next/navigation';

interface Post {
  id: number;
  title: string;
  body: string;
}

interface Comment {
  id: number;
  name: string;
  body: string;
  email: string;
}

interface BlogPostClientProps {
  post: Post;
  comments: Comment[];
}

export default function BlogPostClient({ post, comments }: BlogPostClientProps) {
  const router = useRouter();

  return (
    <article>
      <button onClick={() => router.back()} type="button">
        ← Back
      </button>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  );
}

